    ";\n                    }\n                } else {\n                    const pct = Math.round(stat"
    "e.capture_row / 240 * 100);\n                    status.textContent = `capturing… row ${state.cap"
    "ture_row}/240 (${pct}%)`;\n                }\n            } else if (state.capture_state === 'fail"
    "ed') {\n                status.textContent = 'Capture failed';\n            } else if ((state.capt"
    "ure_state === 'ok' || state.capture_state === 'idle') && state.frame_serial > 0) {\n             "
    "   if (state.frame_serial !== frameSerialShown) {\n                    frameSerialShown = state.f"
    "rame_serial;\n                    capturedTimeText = new Date().toLocaleTimeString();\n           "
    "     }\n                status.textContent = 'Captured ' + capturedTimeText;\n            } else {"
    "\n                status.textContent = 'Click to capture';\n            }\n        }\n\n        async"
    " function captureFrame() {\n            document.getElementById('error').textContent = '';\n      "
    "      try {\n                if (state.project !== 33) {\n                    await fetch('/api/se"
    "lect', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({"
    " project: 33 }) });\n                }\n                if (state.u_rst_n === false) {\n           "
    "         await fetch('/api/reset', { method: 'POST', headers: { 'Content-Type': 'application/jso"
    "n' }, body: JSON.stringify({ reset: false }) });\n                }\n                const res = a"
    "wait fetch('/api/capture', { method: 'POST' });\n                if (res.status === 409) {\n      "
    "              document.getElementById('captureStatus').textContent = 'Capture already in progres"
    "s';\n                } else if (!res.ok) {\n                    document.getElementById('error').t"
    "extContent = `Capture failed: ${res.status}`;\n                }\n            } catch (e) {\n      "
    "          document.getElementById('error').textContent = e.message;\n            }\n        }\n\n   "
    "     async function api(path, body) {\n            document.getElementById('error').textContent ="
    " '';\n            try {\n                const opts = body ? {\n                    method: 'POST',"
    "\n                    headers: { 'Content-Type': 'application/json' },\n                    body: "
    "JSON.stringify(body)\n                } : {};\n                const res = await fetch(path, opts)"
    ";\n                if (!res.ok) {\n                    const text = await res.text();\n            "
    "        throw new Error(`${res.status}: ${text}`);\n                }\n                state = { ."
    "..state, ...await res.json() };\n                updateUi();\n            } catch (e) {\n          "
    "      document.getElementById('error').textContent = e.message;\n            }\n        }\n\n       "
    " function updateOutputWidgets() {\n            if (!currentDescriptor || !currentDescriptor.outpu"
    "ts) return;\n\n            for (const output of currentDescriptor.outputs) {\n                if (o"
    "utput.type === 'leds') {\n                    for (const bit of output.bits) {\n                  "
    "      const on = (state.uo_out >> bit) & 1;\n                        const el = document.getEleme"
    "ntById(`out_led_${bit}`);\n                        if (el) el.classList.toggle('on', on);\n       "
    "             }\n                } else if (output.type === 'seven_seg') {\n                    con"
    "st segs = output.segments;\n                    const segState = {};\n                    for (con"
    "st [name, src] of Object.entries(segs)) {\n                        const [bus, idxStr] = src.spli"
    "t('.');\n                        const idx = parseInt(idxStr, 10);\n                        const "
    "value = bus === 'uio' ? state.uio_value : state.uo_out;\n                        segState[name] ="
    " (value >> idx) & 1;\n                    }\n                    const inverted = ((state.ui_in >>"
    " 4) & 1) !== 0;\n                    for (let i = 0; i < output.digits.length; i++) {\n           "
    "             const selectSrc = output.digits[i].select;\n                        const [bus, idxS"
    "tr] = selectSrc.split('.');\n                        const idx = parseInt(idxStr, 10);\n          "
    "              const value = bus === 'uio' ? state.uio_value : state.uo_out;\n                    "
    "    const selected = (value >> idx) & 1;\n                        const cvs = document.getElement"
    "ById(`seven_seg_digit_${i}`);\n                        if (cvs) {\n                            dra"
    "wSevenSeg(cvs, selected ? segState : {}, inverted);\n                        }\n                  "
    "  }\n                }\n            }\n        }\n\n        function updateUi() {\n            const s"
    "elect = document.getElementById('projectSelect');\n            if (select.value !== String(state."
    "project)) {\n                select.value = state.project;\n                loadDescriptor(state.p"
    "roject);\n            }\n            document.getElementById('projectStatus').textContent = `Curre"
    "nt: ${state.project}`;\n\n            if (!editingFreq) {\n                document.getElementById("
    "'freqValue').textContent = state.clock_freq_hz.toLocaleString();\n            }\n            docum"
    "ent.getElementById('runBtn').textContent = state.clock_running ? 'Stop' : 'Run';\n            doc"
    "ument.getElementById('clockStatus').textContent = state.clock_running ? 'Running' : 'Stopped';\n\n"
    "            updateOutputWidgets();\n            maybeRefreshFrame();\n            updateCaptureSta"
    "tus();\n        }\n\n        function selectProject(project) {\n            api('/api/select', { pro"
    "ject });\n        }\n\n        function setClock(freq) {\n            api('/api/clock', { running: t"
    "rue, freq_hz: freq });\n        }\n\n        function toggleClock() {\n            api('/api/clock',"
    " { running: !state.clock_running, freq_hz: state.clock_freq_hz || 1000 });\n        }\n\n        fu"
    "nction stepClock() {\n            api('/api/step', {});\n        }\n\n        function editFreq() {\n"
    "            if (editingFreq) return;\n            editingFreq = true;\n            const span = do"
    "cument.getElementById('freqValue');\n            const current = state.clock_freq_hz || 1000;\n   "
    "         span.innerHTML = `<input type=\"number\" id=\"freqInput\" value=\"${current}\" min=\"10\" max=\""
    "25000000\">`;\n            const input = document.getElementById('freqInput');\n            input.f"
    "ocus();\n            input.select();\n            input.addEventListener('keydown', (e) => {\n     "
    "           if (e.key === 'Enter') saveFreq();\n                if (e.key === 'Escape') { editingF"
    "req = false; updateUi(); }\n            });\n            input.addEventListener('blur', saveFreq);"
    "\n        }\n\n        function saveFreq() {\n            if (!editingFreq) return;\n            cons"
    "t input = document.getElementById('freqInput');\n            const freq = parseInt(input.value, 1"
    "0);\n            editingFreq = false;\n            if (!isNaN(freq) && freq > 0) {\n               "
    " api('/api/clock', { running: true, freq_hz: freq });\n            } else {\n                updat"
    "eUi();\n            }\n        }\n\n        loadProjects();\n        api('/api/state');\n        setIn"
    "terval(() => api('/api/state'), 250);\n    </script>\n</body>\n</html>\n";
